INSERT INTO recipe_step (recipe_id, position, text) VALUES (8, 3, 'Crumble the pressed tofu into the skillet using your hands or a fork, mimicking the texture of scrambled eggs.');
INSERT INTO recipe_step (recipe_id, position, text) VALUES (8, 4, 'Sprinkle the turmeric, cumin, paprika, salt, and pepper over the tofu mixture. Stir well to evenly distribute the spices.');
INSERT INTO recipe_step (recipe_id, position, text) VALUES (8, 5, 'Allow the tofu scramble to cook for 5-7 minutes, stirring occasionally, until heated through and slightly golden.');
INSERT INTO recipe_step (recipe_id, position, text) VALUES (8, 6, 'If using nutritional yeast, sprinkle it over the tofu scramble and stir to incorporate.');
